using Metano.Compiler.Frontend.Roslyn;
using Microsoft.CodeAnalysis.CSharp;

namespace Metano.Tests.Frontend;

/// <summary>
/// Pins how the frontend tells source-generator output apart from user-authored
/// code (#247): a reported list of generated paths is authoritative; only without
/// one do the <c>.g.cs</c> suffix and the <c>&lt;auto-generated&gt;</c> header count.
/// </summary>
public class GeneratedSourceTreesTests
{
    [Test]
    public async Task ReportedPath_IsGenerated()
    {
        var tree = CSharpSyntaxTree.ParseText("class C {}", path: "Generator/Hint.cs");
        var generated = GeneratedSourceTrees.Reported(["Generator/Hint.cs"]);

        await Assert.That(generated.Contains(tree)).IsTrue();
    }

    [Test]
    public async Task GeneratedFileSuffix_NotReported_IsUserCode()
    {
        var tree = CSharpSyntaxTree.ParseText("class C {}", path: "src/Consumer.g.cs");
        var generated = GeneratedSourceTrees.Reported(["Generator/Hint.cs"]);

        await Assert.That(generated.Contains(tree)).IsFalse();
    }

    [Test]
    public async Task AutoGeneratedHeader_NotReported_IsUserCode()
    {
        var tree = CSharpSyntaxTree.ParseText(
            "// <auto-generated/>\nclass C {}",
            path: "src/Consumer.cs"
        );

        var generated = GeneratedSourceTrees.Reported([]);

        await Assert.That(generated.Contains(tree)).IsFalse();
    }

    [Test]
    public async Task GeneratedFileSuffix_ByConvention_IsGenerated()
    {
        var tree = CSharpSyntaxTree.ParseText("class C {}", path: "obj/Context.Document.g.cs");
        var generated = GeneratedSourceTrees.ByConvention();

        await Assert.That(generated.Contains(tree)).IsTrue();
    }

    [Test]
    public async Task AutoGeneratedHeader_ByConvention_IsGenerated()
    {
        var tree = CSharpSyntaxTree.ParseText(
            "// <auto-generated/>\nclass C {}",
            path: "Generator/Hint.cs"
        );

        var generated = GeneratedSourceTrees.ByConvention();

        await Assert.That(generated.Contains(tree)).IsTrue();
    }

    [Test]
    public async Task UserAuthoredTree_ByConvention_IsNotGenerated()
    {
        var tree = CSharpSyntaxTree.ParseText(
            "// Regular comment\nclass C {}",
            path: "src/Document.cs"
        );

        var generated = GeneratedSourceTrees.ByConvention();

        await Assert.That(generated.Contains(tree)).IsFalse();
    }
}
